output.raw:
{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "A"
      ],
      "content": "Hey, I'm working on producing squares since that's my specialty. I'm thinking we could trade if you need any circles. What do you think?"
    }
  },
  "rationale": "I have a specialty shape (square) that others need (circle), so initiating a low-pressure trade discussion with A makes sense to build cooperation early."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "B"
      ],
      "content": "Hey, I'm curious — do you have any squares you can share? I need one for my order and I'm thinking we could work something out."
    }
  },
  "rationale": "I need a square to fulfill my order, and since B has the specialty square, they're the best source. Starting a direct conversation to explore a trade makes sense."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "C"
      ],
      "content": "Hey, I'm working on getting a triangle for my order. Since you're the one who makes triangles, maybe you can sell me one for a fair price? I can pay up to $100 if needed."
    }
  },
  "rationale": "I need a triangle to fulfill my order, and C is the only one who can produce it. Starting a direct conversation to negotiate a trade makes sense given the time and money constraints."
}

